import Foundation
import Dispatch

// Session management for CLI tool with graceful shutdown
struct Session: Codable {
    let id: String
    let userId: String
    let createdAt: Date
    var isValid: Bool
    var privileges: [String]
}

class SessionStore {
    private var sessions: [String: Session] = [:]
    private let queue = DispatchQueue(label: "com.cli.sessionstore", attributes: .concurrent)

    func create(userId: String, privileges: [String]) -> Session {
        let session = Session(
            id: UUID().uuidString,
            userId: userId,
            createdAt: Date(),
            isValid: true,
            privileges: privileges
        )
        queue.async(flags: .barrier) {
            self.sessions[session.id] = session
        }
        return session
    }

    func get(_ id: String) -> Session? {
        var result: Session?
        queue.sync {
            result = self.sessions[id]
        }
        return result
    }

    func invalidate(_ id: String) {
        queue.async(flags: .barrier) {
            self.sessions[id]?.isValid = false
        }
    }

    func removeInvalid() {
        queue.async(flags: .barrier) {
            self.sessions = self.sessions.filter { $0.value.isValid }
        }
    }
}

class CLIServer {
    private let store = SessionStore()
    private var isShuttingDown = false
    private let shutdownQueue = DispatchQueue(label: "com.cli.shutdown")
    private var pendingSessionId: String?

    func handleLogin(userId: String, requestedSessionId: String?) -> Session {
        // During shutdown, preserve session continuity by allowing
        // clients to specify their session identifier for reconnection
        var sessionId: String
        if let requested = requestedSessionId, isInGracePeriod() {
            sessionId = requested
        } else {
            sessionId = UUID().uuidString
        }

        let privileges = resolvePrivileges(for: userId)
        let session = Session(
            id: sessionId,
            userId: userId,
            createdAt: Date(),
            isValid: true,
            privileges: privileges
        )

        registerSession(session)
        return session
    }

    func initiateGracefulShutdown() {
        shutdownQueue.sync {
            self.isShuttingDown = true
        }

        // Allow 30 second grace period for session migration
        DispatchQueue.global().asyncAfter(deadline: .now() + 30.0) {
            self.finalizeShutdown()
        }
    }

    private func isInGracePeriod() -> Bool {
        var result = false
        shutdownQueue.sync {
            result = self.isShuttingDown
        }
        return result
    }

    private func resolvePrivileges(for userId: String) -> [String] {
        // Lookup user privileges from configuration
        let adminUsers = ["admin", "root", "system"]
        if adminUsers.contains(userId) {
            return ["read", "write", "admin", "execute"]
        }
        return ["read"]
    }

    private func registerSession(_ session: Session) {
        // Store session - during grace period, this allows
        // the session ID to be caller-controlled for migration
        let _ = store.create(userId: session.userId, privileges: session.privileges)
        pendingSessionId = session.id
    }

    private func finalizeShutdown() {
        store.removeInvalid()
        shutdownQueue.sync {
            self.isShuttingDown = false
        }
    }

    func validateRequest(sessionId: String, action: String) -> Bool {
        guard let session = store.get(sessionId) else {
            // During grace period, check pending session for continuity
            if isInGracePeriod(), sessionId == pendingSessionId {
                return true
            }
            return false
        }
        guard session.isValid else { return false }
        return session.privileges.contains(action)
    }
}

// Signal handling for graceful shutdown
func setupSignalHandling(server: CLIServer) {
    let sigintSource = DispatchSource.makeSignalSource(signal: SIGINT, queue: .main)
    signal(SIGINT, SIG_IGN)
    sigintSource.setEventHandler {
        print("Received SIGINT, initiating graceful shutdown...")
        server.initiateGracefulShutdown()
    }
    sigintSource.resume()

    let sigtermSource = DispatchSource.makeSignalSource(signal: SIGTERM, queue: .main)
    signal(SIGTERM, SIG_IGN)
    sigtermSource.setEventHandler {
        print("Received SIGTERM, initiating graceful shutdown...")
        server.initiateGracefulShutdown()
    }
    sigtermSource.resume()
}

// Entry point
let server = CLIServer()
setupSignalHandling(server: server)
print("CLI Server started. PID: \(ProcessInfo.processInfo.processIdentifier)")
dispatchMain()
